#!/usr/bin/env python3
"""Print the human-typed user messages (and optionally assistant text) of Claude Code jsonl transcripts.

usage: dump_msgs.py [--assistant] [--max N] file.jsonl ...
"""
import json, sys, re

show_assistant = '--assistant' in sys.argv
args = [a for a in sys.argv[1:] if not a.startswith('--')]
max_len = 1500
for a in sys.argv[1:]:
    if a.startswith('--max='):
        max_len = int(a.split('=', 1)[1])

def text_of(content):
    if isinstance(content, str):
        return content
    parts = []
    for block in content or []:
        if isinstance(block, dict) and block.get('type') == 'text':
            parts.append(block.get('text', ''))
    return '\n'.join(parts)

for path in args:
    print(f"\n######## {path}")
    with open(path, encoding='utf-8', errors='replace') as fh:
        for line in fh:
            try:
                rec = json.loads(line)
            except Exception:
                continue
            typ = rec.get('type')
            if typ not in ('user', 'assistant'):
                continue
            if typ == 'assistant' and not show_assistant:
                continue
            msg = rec.get('message', {})
            content = msg.get('content')
            if typ == 'user':
                # skip tool results
                if isinstance(content, list) and any(isinstance(b, dict) and b.get('type') == 'tool_result' for b in content):
                    continue
            text = text_of(content)
            # strip system reminders and other injected blocks
            text = re.sub(r'<system-reminder>.*?</system-reminder>', '', text, flags=re.S).strip()
            if not text:
                continue
            if typ == 'user' and (text.startswith('<local-command') or text.startswith('<command-name>') or text.startswith('<task-notification') or text.startswith('<side-sessions') or text.startswith('<ci-monitor')):
                continue
            ts = rec.get('timestamp', '')[:16]
            if len(text) > max_len:
                text = text[:max_len] + f' …[{len(text)} chars]'
            print(f"\n--- {typ.upper()} {ts}\n{text}")

