#!/usr/bin/env python3
"""Find tool results (and assistant text) in Claude Code jsonl transcripts containing a phrase.

usage: find_tool_output.py --phrase="..." [--context=N] [--max=N] file.jsonl ...
Prints the timestamp and the matching block, trimmed to --max chars around the match.
"""
import json, sys, re

phrase = None; ctx = 1500; maxn = 20
args = []
for a in sys.argv[1:]:
    if a.startswith('--phrase='): phrase = a.split('=',1)[1]
    elif a.startswith('--context='): ctx = int(a.split('=',1)[1])
    elif a.startswith('--max='): maxn = int(a.split('=',1)[1])
    else: args.append(a)

def blocks(rec):
    msg = rec.get('message', {})
    content = msg.get('content')
    if isinstance(content, str):
        yield rec.get('type'), content
        return
    for b in content or []:
        if not isinstance(b, dict): continue
        if b.get('type') == 'text':
            yield rec.get('type'), b.get('text','')
        elif b.get('type') == 'tool_result':
            c = b.get('content')
            if isinstance(c, str):
                yield 'tool_result', c
            elif isinstance(c, list):
                for cc in c:
                    if isinstance(cc, dict) and cc.get('type') == 'text':
                        yield 'tool_result', cc.get('text','')
        elif b.get('type') == 'tool_use':
            yield 'tool_use', json.dumps(b.get('input'))

found = 0
for path in args:
    with open(path, encoding='utf-8', errors='replace') as fh:
        for line in fh:
            try: rec = json.loads(line)
            except Exception: continue
            if rec.get('type') not in ('user','assistant'): continue
            ts = rec.get('timestamp','')[:16]
            for kind, text in blocks(rec):
                i = text.find(phrase)
                if i < 0: continue
                start = max(0, i - ctx); end = min(len(text), i + len(phrase) + ctx)
                print(f"\n==== {path.split('/')[-1][:8]} {ts} [{kind}] chars {start}-{end} of {len(text)}")
                print(text[start:end])
                found += 1
                if found >= maxn: sys.exit(0)

